import{_ as d,o as r,c as o,ag as e}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-面向对象设计","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-面向对象设计"},"headers":[],"relativePath":"综合知识/软件工程/面向对象设计.md","filePath":"综合知识/软件工程/面向对象设计.md","lastUpdated":null}'),n={name:"综合知识/软件工程/面向对象设计.md"};function a(l,t,s,g,h,i){return r(),o("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] OO 三大特性（封装/继承/多态）</li><li>[x] OO 设计五大原则（开闭/里氏替换/依赖倒置/单一职责/最少知识）</li><li>[x] OOA 5层5活动</li><li>[x] OOD 三种类（实体类/边界类/控制类）</li><li>[x] UML 四种事物与六种关系</li><li>[x] 用例图（组成/关系/构建阶段）</li><li>[x] 关键 UML 图用途速查</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、oo-三大特性-★" tabindex="-1">一、OO 三大特性 ★ <a class="header-anchor" href="#一、oo-三大特性-★" aria-label="Permalink to &quot;一、OO 三大特性 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：封装隐藏细节、继承复用代码、多态同一接口不同实现。</p></blockquote><table tabindex="0"><thead><tr><th>特性</th><th>核心概念</th><th>考试关键词</th></tr></thead><tbody><tr><td><strong>封装</strong></td><td>隐藏对象内部状态，仅通过公共接口访问</td><td>&quot;将数据和方法绑定&quot;、&quot;信息隐藏&quot;</td></tr><tr><td><strong>继承</strong></td><td>子类获得父类的属性和方法</td><td>&quot;泛化关系&quot;、多重继承</td></tr><tr><td><strong>多态</strong></td><td>同一接口可以有不同的实现</td><td>&quot;同一接口不同实现&quot;、&quot;子类重写父类方法&quot;</td></tr></tbody></table><hr><h3 id="二、oo-设计五大原则-★" tabindex="-1">二、OO 设计五大原则 ★ <a class="header-anchor" href="#二、oo-设计五大原则-★" aria-label="Permalink to &quot;二、OO 设计五大原则 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：开闭是总纲（对扩展开放、对修改关闭），依赖倒置是手段（针对接口编程）。</p></blockquote><table tabindex="0"><thead><tr><th>原则</th><th>一句话</th><th>考试关键词</th></tr></thead><tbody><tr><td><strong>开闭原则 OCP</strong></td><td>不修改原有代码即可变更行为</td><td>&quot;增加字母校验码，不应修改原有代码&quot;</td></tr><tr><td><strong>里氏替换 LSP</strong></td><td>子类可以替换父类，不改参数/返回值/不抛新异常</td><td>&quot;子类方法返回类型与父类完全一致&quot;</td></tr><tr><td><strong>依赖倒置 DIP</strong></td><td>抽象不依赖细节，细节依赖抽象；<strong>针对接口编程</strong></td><td>&quot;针对接口编程，不针对实现编程&quot;</td></tr><tr><td><strong>单一职责 SRP</strong></td><td>一个类只有一个引起变化的原因</td><td>&quot;一个类只做一件事&quot;</td></tr><tr><td><strong>最少知识 LKP</strong></td><td>迪米特法则，最少知识原则</td><td>&quot;减少类之间的交互&quot;</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：开闭原则→修改封闭/扩展开放；依赖倒置→针对接口不是针对实现。里氏替换的核心是<strong>子类行为必须与父类承诺一致</strong>。</p></blockquote><hr><h3 id="三、ooa-5层5活动-★" tabindex="-1">三、OOA 5层5活动 ★ <a class="header-anchor" href="#三、ooa-5层5活动-★" aria-label="Permalink to &quot;三、OOA 5层5活动 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：面向对象分析 = <strong>5个层次 + 5个活动</strong>。</p></blockquote><p><strong>5个层次：</strong> 类与对象层 → 属性层 → 服务层 → 结构层 → 主题层</p><p><strong>5个活动：</strong></p><ol><li>标识对象类</li><li>标识结构 — 识别<strong>泛化关系</strong>和<strong>整体-部分关系</strong></li><li>定义主题</li><li>定义属性</li><li>定义服务</li></ol><p><strong>OOA 基本原则：</strong> 抽象、封装、继承、分类、聚合、关联、消息通信（不含&quot;耦合&quot;）</p><hr><h3 id="四、ood-三种类-★★" tabindex="-1">四、OOD 三种类 ★★ <a class="header-anchor" href="#四、ood-三种类-★★" aria-label="Permalink to &quot;四、OOD 三种类 ★★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>实体类存数据、边界类管界面、控制类协调流程。</strong> 考试高频考题！</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>职责</th><th>典型实例</th></tr></thead><tbody><tr><td><strong>实体类</strong></td><td>映射需求中的实体，保存持久化信息</td><td>用户、课程、订单、商品</td></tr><tr><td><strong>边界类</strong></td><td>封装用例内外流动的信息或数据流</td><td>窗口、通信协议、商品信息页面</td></tr><tr><td><strong>控制类</strong></td><td>协调用例工作的类，处理业务逻辑和流程控制</td><td>身份验证、订单结算、用户登录</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：OOD 三种类<strong>不包括</strong>数据类、抽象类、接口类（这些是迷惑选项）。&quot;用户登录&quot;本身是控制类，&quot;用户登录页面&quot;是边界类，&quot;用户&quot;是实体类。</p></blockquote><hr><h3 id="五、uml-四种事物与六种关系-★" tabindex="-1">五、UML 四种事物与六种关系 ★ <a class="header-anchor" href="#五、uml-四种事物与六种关系-★" aria-label="Permalink to &quot;五、UML 四种事物与六种关系 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：结构事物描述静态（类/接口/构件），行为事物描述动态（交互/状态）。</p></blockquote><p><strong>四种事物：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">事物类型</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>结构事物</strong></td><td>模型的静态部分，描述概念或物理元素</td><td>类、接口、构件、节点</td></tr><tr><td style="text-align:left;"><strong>行为事物</strong></td><td>模型的动态部分，描述跨越时间和空间的行为</td><td>交互、状态机</td></tr><tr><td style="text-align:left;"><strong>分组事物</strong></td><td>模型的组织部分</td><td>包</td></tr><tr><td style="text-align:left;"><strong>注释事物</strong></td><td>模型的解释部分</td><td>注释</td></tr></tbody></table><p><strong>六种关系：</strong></p><table tabindex="0"><thead><tr><th>关系</th><th>说明</th><th>考试关键词</th></tr></thead><tbody><tr><td><strong>依赖</strong></td><td>一个事物变化影响另一个</td><td>使用、调用</td></tr><tr><td><strong>关联</strong></td><td>类之间的结构关系</td><td>Student 选 Course</td></tr><tr><td><strong>聚合</strong></td><td>整体-部分（弱包含，部分可独立）</td><td>University → Student</td></tr><tr><td><strong>组合</strong></td><td>整体-部分（强包含，同生命周期）</td><td>University → Department</td></tr><tr><td><strong>泛化</strong></td><td>特殊/一般，子类替换父类</td><td>继承</td></tr><tr><td><strong>实现</strong></td><td>接口与实现的关系</td><td>implements</td></tr></tbody></table><blockquote><p>⚠️ 关键辨析：聚合（空心菱形）vs 组合（实心菱形）— 聚合的部分可独立存在，组合的部分生命周期与整体一致。</p></blockquote><hr><h3 id="六、用例图-★" tabindex="-1">六、用例图 ★ <a class="header-anchor" href="#六、用例图-★" aria-label="Permalink to &quot;六、用例图 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：用例图三要素 = <strong>参与者 + 用例 + 通信关联</strong>，用例之间有 <strong>包含</strong>、<strong>扩展</strong>、<strong>泛化</strong> 三种关系。</p></blockquote><p><strong>构建用例模型4阶段：</strong> 识别参与者 → 合并需求获得用例 → 细化用例描述 → 调整用例模型（前3个是必需的）</p><p><strong>用例关系：</strong></p><table tabindex="0"><thead><tr><th>关系</th><th>说明</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>包含 <code>&lt;include&gt;</code></strong></td><td>必选的，抽取公共行为</td><td>登录系统 包含于 注册课程</td></tr><tr><td><strong>扩展 <code>&lt;extend&gt;</code></strong></td><td>可选的，条件触发</td><td>参加补考 扩展自 参加考试</td></tr><tr><td><strong>泛化</strong></td><td>父用例到子用例</td><td>支付 泛化出 支付宝支付</td></tr></tbody></table><hr><h3 id="七、关键-uml-图用途速查" tabindex="-1">七、关键 UML 图用途速查 <a class="header-anchor" href="#七、关键-uml-图用途速查" aria-label="Permalink to &quot;七、关键 UML 图用途速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>图类型</th><th style="text-align:center;">类别</th><th>主要用途</th></tr></thead><tbody><tr><td>用例图</td><td style="text-align:center;">—</td><td>描述系统功能需求，用户与系统交互</td></tr><tr><td>类图</td><td style="text-align:center;">结构图</td><td>类内部属性和行为，类之间交互关系</td></tr><tr><td>对象图</td><td style="text-align:center;">结构图</td><td>某一时刻对象实例的静态快照</td></tr><tr><td>包图</td><td style="text-align:center;">结构图</td><td>组织类，表示总体框架结构</td></tr><tr><td>组件图</td><td style="text-align:center;">结构图</td><td>物理组件及依赖关系</td></tr><tr><td>部署图</td><td style="text-align:center;">结构图</td><td>软件到硬件的映射、拓扑结构</td></tr><tr><td>序列图</td><td style="text-align:center;">行为图</td><td><strong>对象间交互顺序和时间流程</strong></td></tr><tr><td>通信图</td><td style="text-align:center;">行为图</td><td>对象间消息传递（协作）</td></tr><tr><td>状态图</td><td style="text-align:center;">行为图</td><td>定义对象的<strong>内部行为</strong>，状态变迁</td></tr><tr><td>活动图</td><td style="text-align:center;">行为图</td><td>业务流程、并发分叉/汇合</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：序列图（顺序图）<strong>属于面向对象设计（UML），不属于结构化设计工具</strong>。状态图描述单个对象的生命周期，活动图描述流程。</p></blockquote>',41)])])}const c=d(n,[["render",a]]);export{b as __pageData,c as default};
